#include <stdio.h>

int add(int a, int b) { return a + b; }
int multiply(int a, int b) { return a * b; }

int compute(int a, int b, int (*operation)(int, int)) {   // callback parameter
    return operation(a, b);
}

int main() {
    int (*fp)(int, int) = add;
    printf("%d\n", fp(2, 3));             // 5, called through the pointer

    printf("%d\n", compute(4, 5, add));       // 9
    printf("%d\n", compute(4, 5, multiply));  // 20 — same compute(), different behavior
    return 0;
}
